// Some portions generated by Claude
/** Node colours: RDF types get palette slots in first-seen order; literals, blank nodes and loading IRIs have their own. */
import { createTypeColorRegistry } from "./graph-type-colors.ts";
import type { GraphNode, GraphNodeType } from "./graph-types.ts";

export const UNTYPED_IRI_TYPE: GraphNodeType = {
  id: "__untyped_iri__",
  label: "No type",
};

// Palette slots in the order types receive them: neighbouring slots differ most in hue (teal, coral, blue, amber,
// violet, green), so the first few types of a graph are easy to tell apart.
export const TYPE_PALETTE = [1, 3, 2, 4, 6, 5].map((index) => ({
  stroke: `var(--graph-explorer-type-${index}-stroke)`,
  fill: `var(--graph-explorer-type-${index}-fill)`,
})) as ReadonlyArray<{ readonly stroke: string; readonly fill: string }>;

export const LITERAL_VISUAL = { stroke: "var(--graph-explorer-literal-stroke)", fill: "var(--graph-explorer-literal-fill)" };

export const BLANK_VISUAL = { stroke: "var(--graph-explorer-blank-stroke)", fill: "var(--graph-explorer-blank-fill)" };

export const LOADING_IRI_VISUAL = { stroke: "var(--graph-explorer-loading-stroke)", fill: "var(--graph-explorer-loading-fill)" };

export function stableStringHash(value: string) {
  let hash = 2166136261;
  for (const character of value) {
    hash ^= character.charCodeAt(0);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}

export const typeColorSlot = createTypeColorRegistry(TYPE_PALETTE.length);

export function typeVisual(typeId: string) {
  return typeId === UNTYPED_IRI_TYPE.id ? LOADING_IRI_VISUAL : TYPE_PALETTE[typeColorSlot(typeId)];
}

/** Datatype and language facet swatches: a stable colour per value that does not use up the type colours. */
export function facetValueVisual(valueId: string) {
  return TYPE_PALETTE[stableStringHash(valueId) % TYPE_PALETTE.length];
}

export function primaryNodeType(node: GraphNode) {
  if (node.kind !== "iri") return null;
  if (node.types === undefined) return null;
  return node.types[0] ?? UNTYPED_IRI_TYPE;
}

export function nodeVisual(node: GraphNode) {
  if (node.kind === "literal") return LITERAL_VISUAL;
  if (node.kind === "blank") return BLANK_VISUAL;
  const primaryType = primaryNodeType(node);
  return primaryType ? typeVisual(primaryType.id) : LOADING_IRI_VISUAL;
}

export function nodeTypeIds(node: GraphNode) {
  if (node.kind === "literal" || node.types === undefined) return [];
  if (node.kind === "blank") return node.types.map((type) => type.id);
  return node.types.length
    ? node.types.map((type) => type.id)
    : [UNTYPED_IRI_TYPE.id];
}
